"""
Context manager for function memoization with LRU eviction.

Usage:
    from memoize_context import Memoize

    with Memoize(maxsize=128) as memo:
        @memo
        def fib(n):
            if n < 2:
                return n
            return fib(n - 1) + fib(n - 2)

        result = fib(100)  # cached after first call
        print(memo.hits, memo.misses)  # cache statistics
"""

from __future__ import annotations

import functools
import hashlib
import json
from collections import OrderedDict
from typing import Any, Callable, TypeVar

F = TypeVar("F", bound=Callable[..., Any])


class Memoize:
    """
    Context manager that provides memoization with LRU eviction.

    Decorate functions with the instance inside a ``with`` block.  Results are
    cached in an ``OrderedDict``; when the cache is full the least-recently-used
    entry is evicted.  The cache is cleared when the context exits.

    Args:
        maxsize: Maximum number of cached results per decorated function.
            Must be positive.

    Example::

        with Memoize(maxsize=64) as memo:
            @memo
            def expensive(x):
                return x ** 2

            expensive(10)  # computed
            expensive(10)  # cache hit
            print(memo.hits)  # 1
    """

    def __init__(self, maxsize: int = 128) -> None:
        if maxsize <= 0:
            raise ValueError(f"maxsize must be positive, got {maxsize}")
        self._maxsize = maxsize
        self._caches: dict[int, OrderedDict[str, Any]] = {}
        self._hits: int = 0
        self._misses: int = 0

    # -- context manager protocol ------------------------------------------

    def __enter__(self) -> Memoize:
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.clear()

    # -- decorator ---------------------------------------------------------

    def __call__(self, func: F) -> F:
        """Return a memoized wrapper for *func*."""
        cache: OrderedDict[str, Any] = OrderedDict()
        self._caches[id(func)] = cache

        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = _make_key(args, kwargs)
            if key in cache:
                cache.move_to_end(key)
                self._hits += 1
                return cache[key]

            self._misses += 1
            result = func(*args, **kwargs)

            cache[key] = result
            if len(cache) > self._maxsize:
                cache.popitem(last=False)
            return result

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper  # type: ignore[return-value]

    # -- stats / management ------------------------------------------------

    @property
    def hits(self) -> int:
        """Total cache hits across all decorated functions."""
        return self._hits

    @property
    def misses(self) -> int:
        """Total cache misses across all decorated functions."""
        return self._misses

    @property
    def size(self) -> int:
        """Total number of entries across all caches."""
        return sum(len(c) for c in self._caches.values())

    def clear(self) -> None:
        """Remove all cached results and reset statistics."""
        for cache in self._caches.values():
            cache.clear()
        self._hits = 0
        self._misses = 0


def _make_key(args: tuple[Any, ...], kwargs: dict[str, Any]) -> str:
    """Build a deterministic string key from positional and keyword args."""
    if not kwargs:
        return repr(args)
    return repr(args) + hashlib.md5(
        json.dumps(kwargs, sort_keys=True, default=str).encode()
    ).hexdigest()


# -- examples --------------------------------------------------------------

def _demo_fibonacci() -> None:
    """Demonstrate memoized recursive Fibonacci."""
    with Memoize(maxsize=256) as memo:
        @memo
        def fib(n: int) -> int:
            if n < 2:
                return n
            return fib(n - 1) + fib(n - 2)

        print(f"fib(50) = {fib(50)}")
        print(f"  hits={memo.hits}, misses={memo.misses}")


def _demo_lru_eviction() -> None:
    """Show LRU eviction when cache is full."""
    with Memoize(maxsize=3) as memo:
        call_count = 0

        @memo
        def square(x: int) -> int:
            nonlocal call_count
            call_count += 1
            return x * x

        for i in range(5):
            square(i)

        # Entries 0 and 1 were evicted (cache holds at most 3)
        square(0)  # miss — must recompute
        square(4)  # hit — still cached

        print(f"  call_count={call_count}")  # 6, not 7
        print(f"  hits={memo.hits}, misses={memo.misses}")


def _demo_kwargs() -> None:
    """Memoize functions called with keyword arguments."""
    with Memoize() as memo:
        @memo
        def greet(name: str, greeting: str = "Hello") -> str:
            return f"{greeting}, {name}!"

        print(greet("Alice"))
        print(greet("Alice"))  # hit
        print(greet("Alice", greeting="Hi"))  # miss — different kwargs
        print(f"  hits={memo.hits}, misses={memo.misses}")


if __name__ == "__main__":
    print("=== Fibonacci ===")
    _demo_fibonacci()
    print("\n=== LRU Eviction ===")
    _demo_lru_eviction()
    print("\n=== Keyword Arguments ===")
    _demo_kwargs()

"""Tests for memoize_context.Memoize."""

from __future__ import annotations

import pytest

from memoize_context import Memoize


class TestMemoizeBasic:
    """Core memoization behavior."""

    def test_cache_hit(self):
        with Memoize() as memo:
            call_count = 0

            @memo
            def double(x):
                nonlocal call_count
                call_count += 1
                return x * 2

            double(5)
            double(5)
            assert call_count == 1
            assert memo.hits == 1
            assert memo.misses == 1

    def test_different_args_are_different_entries(self):
        with Memoize() as memo:
            @memo
            def identity(x):
                return x

            assert identity(1) == 1
            assert identity(2) == 2
            assert memo.misses == 2
            assert memo.hits == 0

    def test_kwargs_work(self):
        with Memoize() as memo:
            @memo
            def add(a, b=0):
                return a + b

            assert add(1, b=2) == 3
            assert add(1, b=2) == 3
            assert memo.hits == 1

    def test_preserves_function_metadata(self):
        with Memoize() as memo:
            @memo
            def documented(x):
                """My docstring."""
                return x

            assert documented.__name__ == "documented"
            assert documented.__doc__ == "My docstring."


class TestLRUEviction:
    """LRU eviction when cache is full."""

    def test_evicts_oldest(self):
        with Memoize(maxsize=2) as memo:
            call_count = 0

            @memo
            def f(x):
                nonlocal call_count
                call_count += 1
                return x

            f(1)  # cache: [1]
            f(2)  # cache: [1, 2]
            f(3)  # cache: [2, 3] — 1 evicted
            assert call_count == 3

            f(1)  # cache miss — must recompute
            assert call_count == 4
            assert memo.misses == 4

    def test_lookup_promotes_entry(self):
        with Memoize(maxsize=2) as memo:
            call_count = 0

            @memo
            def f(x):
                nonlocal call_count
                call_count += 1
                return x

            f(1)  # cache: [1]
            f(2)  # cache: [1, 2]
            f(1)  # hit, promotes 1: cache: [2, 1]
            f(3)  # evicts 2: cache: [1, 3]
            assert call_count == 3

            f(2)  # miss — 2 was evicted
            assert call_count == 4

    def test_update_existing_does_not_grow(self):
        with Memoize(maxsize=2) as memo:
            @memo
            def f(x):
                return x * 10

            f(1)
            f(1)  # same key, should not evict
            assert memo.size <= 2


class TestContextManager:
    """Context manager lifecycle."""

    def test_clears_cache_on_exit(self):
        memo = Memoize()

        @memo
        def f(x):
            return x

        with memo:
            f(1)
            assert memo.size == 1

        assert memo.size == 0
        assert memo.hits == 0
        assert memo.misses == 0

    def test_returns_self_on_enter(self):
        with Memoize() as memo:
            assert isinstance(memo, Memoize)


class TestValidation:
    """Input validation."""

    def test_zero_maxsize_raises(self):
        with pytest.raises(ValueError, match="positive"):
            Memoize(maxsize=0)

    def test_negative_maxsize_raises(self):
        with pytest.raises(ValueError, match="positive"):
            Memoize(maxsize=-5)


class TestEdgeCases:
    """Edge cases and special values."""

    def test_none_argument(self):
        with Memoize() as memo:
            @memo
            def f(x):
                return x is None

            assert f(None) is True
            assert f(None) is True
            assert memo.hits == 1

    def test_tuple_argument(self):
        with Memoize() as memo:
            @memo
            def f(x):
                return sum(x)

            assert f((1, 2, 3)) == 6
            assert f((1, 2, 3)) == 6
            assert memo.hits == 1

    def test_multiple_decorated_functions(self):
        with Memoize(maxsize=10) as memo:
            @memo
            def add(a, b):
                return a + b

            @memo
            def mul(a, b):
                return a * b

            add(1, 2)
            mul(1, 2)
            add(1, 2)
            mul(1, 2)
            assert memo.hits == 2
            assert memo.misses == 2

    def test_exception_in_function_not_cached(self):
        """Functions that raise should not have their result cached."""
        with Memoize() as memo:
            call_count = 0

            @memo
            def flaky(x):
                nonlocal call_count
                call_count += 1
                if call_count == 1:
                    raise ValueError("boom")
                return x

            with pytest.raises(ValueError):
                flaky(1)

            assert flaky(1) == 1  # should retry, not serve cached error
            assert call_count == 2
            assert memo.misses == 2
